function knifeScene(){let good=0;return [R_('— 칼날을 쥔 손 —'),E_('n','부집사님. 발렌하임 영애는 자존심이 대단히 강한 분입니다. 무엇을 빼앗는 이야기보다, 무엇을 지킬 수 있는지를 먼저 알려드리는 편이 훨씬 잘 통하지요.'),K_('n','피가 보이면 들어간다. 그 이하의 소란은 참지.'),
  CE('앉지는 말고 그대로 서 계세요. 하인에게 의자를 내주는 법은 배운 적이 없으니.'),
  C({t:'«어젯밤 일에 관한 소문을, 제가 막아 드리겠습니다.» (지킬 수 있는 것)',go:()=>{good++;},r:[CE('……대가가 뭐지? 세상에 공짜는 없는 법이니까.')]},{t:'«영애께서는 이 성을 떠나셔야 합니다.» (빼앗는 이야기)',r:[CE('감히 네까짓 게!')]}),
  C({t:'«영애의 명예는 영애 스스로 지키시면 됩니다. 저는 길만 열어 드릴게요.»',go:()=>{good++;}},{t:'«전하께서 결정하신 일입니다.»'}),
  {fn:()=>{const safe=good>=2&&(S.rep>=70||S.f.marta_ally||hearts('kairan')>=9);
    if(safe)return [CE('……네 말이 맞아. 그래서 더 역겨워.'),R_('세실리아는 은장도를 쥔 손을 한참 떨다가, 탁자 위에 내려놓았다.'),CE('오늘 당장 떠나지. 대신, 소문 하나라도 새어 나가면— 그땐 너부터다.'),R_('(평판이 높고 말이 통했다. 아무도 다치지 않았다.)'),once(()=>{S.f.ceciliaGone=1;S.rep=Math.min(100,S.rep+8);addPtsQ('kairan',60);})];
    return [CE('네 말이 전부 맞아. 그래서 더 역겨워. 나를 이 꼴로 만든 네 얼굴에, 평생 잊지 못할 선물을 남기고 갈 거야.'),R_('은빛 칼날이 번쩍였다. 에레나는 맨손으로 칼날을 움켜쥐었다.'),K_('a','……피가 보이면 들어간다고 했다.'),K_('a','저 여자를 지하에 가둬.'),
      R_('— 살아 있다 —'),K_('n','네 거래는 유효해. 소문은 내가 덮는다. 그건 네가 얻어낸 결과다, 에레나. 하지만 이건 아니야. 손 펴. 지금.'),R_('정오가 지나, 세실리아는 남쪽으로 향하는 마차에 실려 떠났다.'),K_('n','내 관대함은 너에게만 해당하는 것이지, 아무에게나 베푸는 자비가 아니야. 두 번 다시 그걸 시험하지 마라.'),
      once(()=>{S.f.ceciliaGone=1;S.injury=7;S.f.handScar=1;addPtsQ('kairan',100);}),R_('(왼손을 다쳤다. 일주일 동안 무리할 수 없다. 영지 시찰은 취소되었다.)')];}}];}
