const ENDINGS={
  duchess:{t:'에레나, 라는 이름으로',role:'대공의 약혼녀',desc:'베르티에의 에레나로서, 카이런의 곁에 서게 되었다.'},
  lover:{t:'둘만 아는 이름',role:'부집사 (비밀 연인)',desc:'사람들 앞에선 에렌, 둘만 있을 땐 에레나.'},
  steward:{t:'성의 시간을 지키는 사람',role:'집사 대리',desc:'에드먼드의 뒤를 이어 아르젠트 성의 집사 대리가 되었다.'},
  renew:{t:'북부에 남다',role:'부집사',desc:'라우렌의 요구는 거절되었다. 부집사 에렌의 북부 생활은 계속된다.'},
  home:{t:'남부로 가는 마차',role:'—',desc:'에레나는 남부로 돌아가는 마차에 올랐다.'},
};
function judgeEnding(){
  const k=hearts('kairan');
  if(k>=10&&S.f.knows&&S.f.k10==='yes'&&S.rep>=50)return 'duchess';
  if(k>=8&&S.f.knows)return 'lover';
  if(S.rep>=80&&(S.seen.e6||S.rep>=90))return 'steward';
  if(S.rep<25&&k<4)return 'home';
  return 'renew';
}
function endingScene(missed){
  const e=judgeEnding(),E=ENDINGS[e];
  const L={
    duchess:[K_('n','라우렌 베르티에에게 답장을 보냈다. «베르티에의 에레나는 아르젠트 대공의 약혼녀다. 혼약은 무효다.»'),M('s','네, 네에?!'),K_('b','네가 «에렌»이 아닌 네 이름으로 내 옆에 설 수 있는 날을 반드시 만들겠다고 했지.'),K_('h','오늘이다.'),M('b','……네, 카이런.')],
    lover:[K_('n','라우렌의 요구는 거절했다. 넌 내 부집사다. 누구에게도 넘기지 않는다.'),K_('b','……그리고 둘만 있을 땐, 전하라고 부르지 마라.'),M('b','……네, 카이런.')],
    steward:[K_('n','에드먼드가 은퇴를 청했다. 후임으로 너를 추천하더군.'),E_('h','이 시계는 이제 당신 것입니다, 집사 대리님.'),K_('n','주급은 7골드다. 불만 있나.'),M('h','없습니다, 전하!')],
    renew:[K_('n','라우렌의 요구는 거절했다. 대공가 사람을 내놓으라는 건 북부에 대한 모욕이다.'),M('h','감사합니다, 전하!'),K_('n','……내년에도 차는 네가 내려라.')],
    home:[K_('n','라우렌 베르티에가 사람을 보냈다. 너를 붙잡을 명분이, 나에게는 없군.'),R_('그는 고개를 들지 않았다.'),R_('다음 날 아침, 에레나는 남부로 가는 마차에 올랐다.')],
  }[e];
  startDialog('kairan',[R_('— 결말의 날 (게임 오리지널) —'),...(missed?[R_('밤늦게, 에드먼드가 전하의 결정을 전하러 왔다.')]:[]),...L,R_(`★ 엔딩: «${E.t}» — ${E.desc}`)],()=>{S.ending=e;S.role=E.role;
    if(e==='duchess'){S.f.public=1;S.sus=0;}if(e==='steward')S.wage=7;
    logEv('엔딩: '+E.t,null);save();hud();if(e==='home')showHomeEnd();else toast('엔딩 이후에도 일상이 계속됩니다');});
}
